"""
========== TEST ALL SHAPE TYPES ==========
Sends every supported canvas message type
one at a time, every 3 seconds.
==========================================
"""

import asyncio
import websockets
import json

MESSAGES = [
    {
        "type": "add_text",
        "payload": { "text": "Plain text label", "x": 100, "y": 80, "color": "black", "size": "l" }
    },
    {
        "type": "add_note",
        "payload": { "text": "Violet sticky note — AI provocation goes here", "x": 350, "y": 80, "color": "violet" }
    },
    {
        "type": "add_note",
        "payload": { "text": "Yellow sticky note", "x": 600, "y": 80, "color": "yellow" }
    },
    {
        "type": "add_geo",
        "payload": { "geo": "rectangle", "text": "Rectangle", "x": 100, "y": 220, "w": 180, "h": 100, "color": "blue", "fill": "semi" }
    },
    {
        "type": "add_geo",
        "payload": { "geo": "ellipse", "text": "Ellipse", "x": 320, "y": 220, "w": 180, "h": 100, "color": "green", "fill": "semi" }
    },
    {
        "type": "add_geo",
        "payload": { "geo": "diamond", "text": "Diamond", "x": 540, "y": 200, "w": 160, "h": 130, "color": "orange", "fill": "semi" }
    },
    {
        "type": "add_geo",
        "payload": { "geo": "triangle", "text": "Triangle", "x": 740, "y": 220, "w": 160, "h": 120, "color": "red", "fill": "semi" }
    },
    {
        "type": "add_geo",
        "payload": { "geo": "hexagon", "text": "Hexagon", "x": 940, "y": 210, "w": 160, "h": 130, "color": "violet", "fill": "semi" }
    },
    {
        "type": "add_arrow",
        "payload": { "x1": 190, "y1": 270, "x2": 320, "y2": 270, "label": "connects", "color": "black" }
    },
    {
        "type": "add_arrow",
        "payload": { "x1": 500, "y1": 270, "x2": 540, "y2": 270, "label": "", "color": "red" }
    },
    {
        "type": "add_frame",
        "payload": { "name": "AI Analysis Zone", "x": 100, "y": 400, "w": 500, "h": 250 }
    },
    {
        "type": "add_image",
        "payload": {
            "url": "data:image/jpeg;base64,",
            "x": 650, "y": 400, "w": 280, "h": 200,
            "name": "test-image"
        }
    },
    {
        "type": "set_camera",
        "payload": { "x": -50, "y": -50, "zoom": 0.7 }
    },
]

async def test():
    uri = "ws://localhost:8000/ws"
    print(f"Connecting to {uri}...")
    async with websockets.connect(uri) as ws:
        # consume initial ping
        msg = await ws.recv()
        print(f"Backend says: {json.loads(msg)}")

        for i, message in enumerate(MESSAGES):
            print(f"\n[{i+1}/{len(MESSAGES)}] Sending: {message['type']} — {message['payload']}")
            await ws.send(json.dumps(message))
            await asyncio.sleep(3)

        print("\n✓ All shape types sent! Check your browser.")
        await asyncio.sleep(2)

asyncio.run(test())
